python3 << 'EOF'
import json

with open('/app/resources/treasury_bulletin_1991_09.json', 'r') as f:
    data = json.load(f)

# Search for any table data in the JSON
def find_tables(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            new_path = f"{path}.{key}" if path else key
            if isinstance(value, (dict, list)):
                results.extend(find_tables(value, new_path))
            elif "saving" in str(key).lower() or "saving" in str(value).lower():
                results.append(f"{new_path}: {value}")
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_tables(item, f"{path}[{i}]"))
    return results

results = find_tables(data)
for r in results[:20]:
    print(r)
EOF
